function knapsack(A, B, C) {
    const N = B.length;
    // Create DP table and initialize with -1
    const DP = Array.from({ length: N + 1 }, () => Array(C + 1).fill(-1));

    function f(N, C) {
        if (N === 0 || C === 0) return 0;

        if (DP[N][C] !== -1) return DP[N][C];

        // Don't take
        let ans1 = f(N - 1, C);

        // Take it
        let ans2 = 0;
        if (B[N - 1] <= C) {
            ans2 = A[N - 1] + f(N - 1, C - B[N - 1]);
        }

        DP[N][C] = Math.max(ans1, ans2);
        return DP[N][C];
    }

    return f(N, C);
}
// ✅ Sample input
const values = [60, 100, 120]; // A
const weights = [10, 20, 30];  // B
const capacity = 50;           // C
const result = knapsack(values, weights, capacity);
console.log("Max knapsack value:", result);
